# -*- coding: utf-8 -*-
"""桌面壳常驻的 Console 静态资源服务。"""
from __future__ import annotations

import logging
import socket
import threading
import time
from pathlib import Path

import uvicorn
from fastapi import FastAPI, HTTPException
from starlette.responses import FileResponse

from ..utils.console_static import (
    CONSOLE_INDEX_CACHE_HEADERS,
    ConsoleAssetFiles,
    resolve_console_static_dir,
)


logger = logging.getLogger(__name__)


def create_desktop_console_static_app(static_dir: str) -> FastAPI:
    """创建只提供 Console 文件的最小 ASGI 应用，不承载任何 API。"""
    console_dir = Path(static_dir).resolve()
    index = console_dir / "index.html"
    if not index.is_file():
        raise ValueError("Console 静态目录缺少 index.html")

    app = FastAPI(
        docs_url=None,
        redoc_url=None,
        openapi_url=None,
    )
    assets = console_dir / "assets"
    if assets.is_dir():
        app.mount(
            "/assets",
            ConsoleAssetFiles(directory=str(assets)),
            name="assets",
        )

    def serve_index() -> FileResponse:
        return FileResponse(index, headers=CONSOLE_INDEX_CACHE_HEADERS)

    @app.get("/{full_path:path}")
    def serve_console(full_path: str):
        if full_path in {"docs", "redoc", "openapi.json"}:
            raise HTTPException(status_code=404, detail="Not Found")
        if full_path == "api" or full_path.startswith("api/"):
            raise HTTPException(status_code=404, detail="Not Found")
        if full_path == "workflow-plus/page":
            from starlette.responses import HTMLResponse

            from ..workflow_plus.page import PAGE_HTML

            return HTMLResponse(PAGE_HTML, headers={
                "Cache-Control": "no-cache, no-store, must-revalidate, max-age=0",
            })
        if full_path:
            requested = (console_dir / full_path).resolve()
            try:
                requested.relative_to(console_dir)
            except ValueError:
                raise HTTPException(status_code=404, detail="Not Found") from None
            if requested.is_file():
                if requested.name.lower() == "index.html":
                    return serve_index()
                return FileResponse(
                    requested,
                    headers={"Cache-Control": "public, max-age=86400"},
                )
        return serve_index()

    return app


class DesktopConsoleStaticServer:
    """在壳生命周期内固定 origin 的 Console 静态服务。"""

    def __init__(
        self,
        *,
        static_dir: str | None = None,
        host: str = "127.0.0.1",
    ) -> None:
        self._host = host
        self._static_dir = static_dir or resolve_console_static_dir()
        self._lock = threading.Lock()
        self._server: uvicorn.Server | None = None
        self._thread: threading.Thread | None = None
        self._origin = ""

    @property
    def origin(self) -> str:
        return self._origin

    def start(self, timeout: float = 2.0) -> str:
        """启动一次并返回固定 origin；失败不保留半启动线程。"""
        with self._lock:
            if self._origin:
                return self._origin
            app = create_desktop_console_static_app(self._static_dir)
            listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            listener.bind((self._host, 0))
            listener.listen()
            port = int(listener.getsockname()[1])
            config = uvicorn.Config(
                app,
                log_level="warning",
                access_log=False,
            )
            server = uvicorn.Server(config)
            thread = threading.Thread(
                target=server.run,
                kwargs={"sockets": [listener]},
                name="eazybot-console-static",
                daemon=True,
            )
            self._server = server
            self._thread = thread
            thread.start()
        deadline = time.monotonic() + max(0.0, timeout)
        while thread.is_alive() and not server.started:
            if time.monotonic() >= deadline:
                break
            time.sleep(0.01)
        if server.started:
            origin = f"http://{self._host}:{port}"
            with self._lock:
                self._origin = origin
            logger.info("桌面 Console 静态服务已启动: port=%s", port)
            return origin
        self.stop()
        try:
            listener.close()
        except OSError:
            pass
        raise RuntimeError("桌面 Console 静态服务启动失败")

    def stop(self, timeout: float = 2.0) -> None:
        """停止本壳创建的静态服务，不影响任何后端槽位。"""
        with self._lock:
            server = self._server
            thread = self._thread
            self._server = None
            self._thread = None
            self._origin = ""
        if server is not None:
            server.should_exit = True
        if thread is not None and thread is not threading.current_thread():
            thread.join(timeout=max(0.0, timeout))
